begin;
create table public.battle_classes(
 id text primary key check(id in('warrior','wizard','ninja','guardian','rogue')),
 display_name text not null,attack_style text not null,defensive_style text not null,
 visual_identity text not null,ability_metadata jsonb not null default '[]'
);
insert into public.battle_classes(id,display_name,attack_style,defensive_style,visual_identity) values
 ('warrior','Warrior','Heavy pressure, endurance and guard breaking','Brace, parry and withstand','impact'),
 ('wizard','Wizard','Magic, resource management and planned combinations','Barriers, mitigation and control','orbit'),
 ('ninja','Ninja','Speed, rapid combinations and adaptation','Evasion and repositioning','afterimage'),
 ('guardian','Guardian','Counters and punishment of reckless commitment','Blocking, shielding and patience','barrier'),
 ('rogue','Rogue','Risk, deception and exploiting openings','Misdirection and disruption','misdirection');
create table public.battle_identities(
 user_id uuid primary key references auth.users(id) on delete cascade,
 class_id text not null references public.battle_classes(id),determination_version integer not null,
 determined_at timestamptz not null default now(),acknowledged_at timestamptz
);
-- Private definitions and audit sessions never have direct client SELECT grants.
create table public.awakening_questions(
 version integer not null,id text not null,category text not null check(category in('combat','everyday','determinant')),
 prompt text not null,options jsonb not null check(jsonb_typeof(options)='array'),
 pair text[],active boolean not null default true,primary key(version,id)
);
create table public.awakening_sessions(
 id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users(id) on delete cascade,
 version integer not null default 1,questions jsonb not null,answers jsonb not null default '{}',
 determinants_added boolean not null default false,created_at timestamptz not null default now(),
 expires_at timestamptz not null default now()+interval '7 days',completed_at timestamptz,
 result_class text references public.battle_classes(id),score_audit jsonb
);
do $$declare t text;begin foreach t in array array['battle_classes','battle_identities','awakening_questions','awakening_sessions'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('revoke all on public.%I from public,anon,authenticated',t);
end loop;end $$;
grant select on public.battle_classes to authenticated;
grant select(user_id,class_id) on public.battle_identities to authenticated;
create policy "Battle class registry" on public.battle_classes for select to authenticated using(true);
create policy "Public battle identity" on public.battle_identities for select to authenticated using(true);

create function public.kaidra_immutable_class() returns trigger language plpgsql set search_path='' as $$begin
 if new.user_id is distinct from old.user_id or new.class_id is distinct from old.class_id
 or new.determination_version is distinct from old.determination_version or new.determined_at is distinct from old.determined_at then
 raise exception 'A determined class is permanent';end if;return new;
end $$;
create trigger kaidra_immutable_class before update on public.battle_identities for each row execute function public.kaidra_immutable_class();

drop policy "Profile progression" on public.battle_stats;
create policy "Own private progression" on public.battle_stats for select to authenticated using(user_id=auth.uid());

-- Preserve legitimate editing while closing arbitrary-column/moderation and TRUNCATE access.
revoke all on public.profiles from public,anon,authenticated;
grant select on public.profiles to anon,authenticated;
grant insert(id,username,display_name,avatar_url,bio,birthdate,interests,status_text,profile_template,recommendation_preferences) on public.profiles to authenticated;
grant update(username,display_name,avatar_url,bio,birthdate,interests,status_text,profile_template,recommendation_preferences) on public.profiles to authenticated;
create function public.kaidra_guard_profile_identity() returns trigger language plpgsql set search_path='' as $$begin
 if current_user in('anon','authenticated') and
 ((tg_op='UPDATE' and (new.id is distinct from old.id or new.created_at is distinct from old.created_at or new.onboarding_completed is distinct from old.onboarding_completed))
 or new.is_banned or new.is_restricted or new.restriction_reason is not null or new.restricted_until is not null) then
 raise exception 'Use authorized actions for protected account fields';end if;return new;
end $$;
create trigger kaidra_guard_profile_identity before insert or update on public.profiles for each row execute function public.kaidra_guard_profile_identity();

create function public.kaidra_battle_identity(target_user uuid default auth.uid()) returns jsonb language sql stable security definer set search_path='' as $$
 select case when auth.uid() is not null then (select jsonb_build_object('class_id',i.class_id,'display_name',c.display_name,'attack_style',c.attack_style,'defensive_style',c.defensive_style,'visual_identity',c.visual_identity,'ability_metadata',c.ability_metadata,'league_label',null,'acknowledged',case when i.user_id=auth.uid() then i.acknowledged_at is not null end) from public.battle_identities i join public.battle_classes c on c.id=i.class_id where i.user_id=target_user) end;
$$;

alter function public.kaidra_profile_social(uuid) rename to kaidra_profile_social_internal;
revoke all on function public.kaidra_profile_social_internal(uuid) from public,anon,authenticated;
create function public.kaidra_profile_social(target_user uuid) returns jsonb language sql stable security definer set search_path='' as $$
 select (public.kaidra_profile_social_internal(target_user)-'stats')||jsonb_build_object('stats',case when target_user=auth.uid() then (select to_jsonb(s) from public.battle_stats s where user_id=auth.uid()) end,'identity',public.kaidra_battle_identity(target_user));
$$;
alter function public.kaidra_battle_state(uuid) rename to kaidra_battle_state_internal;
revoke all on function public.kaidra_battle_state_internal(uuid) from public,anon,authenticated;
create function public.kaidra_battle_state(target_battle uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare data jsonb;begin
 data:=public.kaidra_battle_state_internal(target_battle);
 return data||jsonb_build_object('participants',(select jsonb_agg(p||jsonb_build_object('identity',public.kaidra_battle_identity((p->>'id')::uuid))) from jsonb_array_elements(data->'participants') p),
 'rewards',coalesce((select jsonb_agg(r) from jsonb_array_elements(data->'rewards') r where r->>'user_id'=auth.uid()::text),'[]'::jsonb));
end $$;

alter function public.kaidra_battle_create(uuid,uuid,text,text,jsonb,uuid) rename to kaidra_battle_create_internal;
revoke all on function public.kaidra_battle_create_internal(uuid,uuid,text,text,jsonb,uuid) from public,anon,authenticated;
create function public.kaidra_battle_create(target_conversation uuid,target_user uuid,topic text,stance text,context jsonb default '{}',request_id uuid default gen_random_uuid()) returns uuid language plpgsql security definer set search_path='' as $$begin
 if not exists(select 1 from public.battle_identities where user_id=auth.uid()) then raise exception 'Awaken your battle identity before challenging';end if;
 return public.kaidra_battle_create_internal(target_conversation,target_user,topic,stance,context,request_id);
end $$;
alter function public.kaidra_battle_action(uuid,text,text) rename to kaidra_battle_action_internal;
revoke all on function public.kaidra_battle_action_internal(uuid,text,text) from public,anon,authenticated;
create function public.kaidra_battle_action(target_battle uuid,action text,value text default '') returns void language plpgsql security definer set search_path='' as $$begin
 if action='accept' and not exists(select 1 from public.battle_identities where user_id=auth.uid()) then raise exception 'Awaken your battle identity before accepting';end if;
 perform public.kaidra_battle_action_internal(target_battle,action,value);
end $$;

-- Version 1: private question pool (12 combat + 12 everyday + 20 pair determinants).
insert into public.awakening_questions(version,id,category,prompt,options,pair)
select version,id,category,prompt,options,pair from jsonb_to_recordset($pool$[{"version":1,"id":"pattern","prompt":"You are falling behind, but you notice a repeating pattern. What comes naturally?","category":"combat","options":[{"id":"18da25f21e8f","text":"Absorb a little more pressure and commit hard when the opening arrives.","weights":[4,1,2,3,1]},{"id":"34544f2d41d0","text":"Test the pattern once more before building a reliable response.","weights":[1,4,2,3,2]},{"id":"d512e6cd36f5","text":"Change your rhythm immediately and see how they adjust.","weights":[2,2,4,1,2]},{"id":"e64a40419a15","text":"Let them repeat it while preparing a measured response.","weights":[2,2,1,4,2]},{"id":"3f5979ac1d30","text":"Act as if you missed it and encourage them to overcommit.","weights":[1,3,3,1,4]}],"pair":null},{"version":1,"id":"pressure","prompt":"Someone keeps forcing you to react. How do you regain control?","category":"combat","options":[{"id":"fc4f1f2ecada","text":"Commit to one decisive push instead of retreating again.","weights":[4,1,3,3,1]},{"id":"4c48a630831a","text":"Identify what makes their pressure sustainable and interrupt it.","weights":[1,4,2,3,2]},{"id":"fd0049958770","text":"Change distance and timing so the same approach stops working.","weights":[2,3,4,1,2]},{"id":"492287063f1f","text":"Hold a dependable position and wait for the pressure to weaken.","weights":[2,2,2,4,2]},{"id":"3f6bfc817738","text":"Leave an apparent opening and turn their confidence against them.","weights":[1,4,2,1,4]}],"pair":null},{"version":1,"id":"opening","prompt":"An opening appears, but you cannot see everything behind it. What do you do?","category":"combat","options":[{"id":"dc5fd556f373","text":"Take it decisively and remain ready to withstand the response.","weights":[4,1,2,3,2]},{"id":"336497c9d4d0","text":"Check what created the opening before committing.","weights":[2,4,2,2,2]},{"id":"7072554f9258","text":"Test it with a small, quick move that leaves another route open.","weights":[2,2,4,2,2]},{"id":"b4fac3b51aee","text":"Keep your safe position until the opening becomes dependable.","weights":[2,3,1,4,2]},{"id":"a21a657e3641","text":"Make the opening seem less interesting, then use it unexpectedly.","weights":[2,3,2,1,4]}],"pair":null},{"version":1,"id":"resources","prompt":"You have enough energy for only a few more decisive exchanges. What changes?","category":"combat","options":[{"id":"8d9dac8a3595","text":"Choose one clear commitment and make it count.","weights":[4,2,2,3,1]},{"id":"5337967c6ad6","text":"Spend only on actions that support a connected plan.","weights":[1,4,2,2,2]},{"id":"cf3ebb04f8ff","text":"Use smaller actions and adjust as new information arrives.","weights":[2,3,4,1,2]},{"id":"f3dfadbcb3a7","text":"Avoid unnecessary exchanges and preserve a dependable response.","weights":[2,2,1,4,3]},{"id":"c06831a06b40","text":"Make the other person spend first, even if the bait is risky.","weights":[1,4,2,1,4]}],"pair":null},{"version":1,"id":"setback","prompt":"Your best approach just failed. What is your next move?","category":"combat","options":[{"id":"16ab10f10285","text":"Regroup and try again with a stronger commitment.","weights":[4,2,2,3,1]},{"id":"ecc57168fab3","text":"Work out which assumption failed before changing the plan.","weights":[1,4,2,3,2]},{"id":"6d81f78a0a30","text":"Switch approaches quickly instead of defending the old one.","weights":[2,3,4,1,2]},{"id":"8ce63a541491","text":"Stabilize first so the setback cannot become a collapse.","weights":[2,2,1,4,2]},{"id":"074cc6e7c370","text":"Make them expect another attempt, then exploit that expectation.","weights":[2,3,2,1,4]}],"pair":null},{"version":1,"id":"underestimated","prompt":"An opponent treats you as if you cannot threaten them. How do you respond?","category":"combat","options":[{"id":"8f2395777d28","text":"Make a direct commitment that they cannot dismiss.","weights":[4,2,2,3,1]},{"id":"b16953d37c2e","text":"Use the time they give you to assemble a stronger position.","weights":[1,4,3,2,2]},{"id":"d2776289e846","text":"Change pace before they can settle into an easy rhythm.","weights":[2,2,4,2,2]},{"id":"76310c96067b","text":"Stay disciplined and let their carelessness become the opening.","weights":[3,2,1,4,2]},{"id":"1376932cd614","text":"Keep the impression alive until it can be used against them.","weights":[1,4,2,1,4]}],"pair":null},{"version":1,"id":"uncertainty","prompt":"You meet an unfamiliar opponent. What do you try to learn first?","category":"combat","options":[{"id":"795a5fe3e409","text":"How they respond when a clear boundary is pushed.","weights":[4,2,2,3,1]},{"id":"8e852d40f87e","text":"Which decisions fit into a repeatable plan.","weights":[1,4,2,2,3]},{"id":"b1a8d34fb133","text":"How quickly they adjust to changing circumstances.","weights":[2,2,4,1,2]},{"id":"3c87e85e8451","text":"What they do when their first attempt meets resistance.","weights":[2,3,1,4,2]},{"id":"af07f5348680","text":"Which expectations they rely on without questioning them.","weights":[1,3,3,1,4]}],"pair":null},{"version":1,"id":"momentum","prompt":"You have momentum, but a reckless move could throw it away. What do you do?","category":"combat","options":[{"id":"f18916ccd20d","text":"Keep pressure consistent rather than giving up the initiative.","weights":[4,1,3,3,1]},{"id":"30fb7eb75360","text":"Use the advantage to set up the next two exchanges.","weights":[1,4,2,3,2]},{"id":"539402d8d9fb","text":"Vary the approach so the advantage stays flexible.","weights":[2,2,4,1,2]},{"id":"a55713e47cad","text":"Consolidate the advantage and make them take the next risk.","weights":[3,2,1,4,2]},{"id":"1e0209b251ad","text":"Offer them a tempting route back and prepare for their response.","weights":[2,3,2,1,4]}],"pair":null},{"version":1,"id":"commitment","prompt":"A tense exchange has reached a standstill. How do you break it?","category":"combat","options":[{"id":"7d6ed8220943","text":"Take responsibility for the first meaningful commitment.","weights":[4,1,2,3,1]},{"id":"18653afaf71f","text":"Change the conditions that made the standstill possible.","weights":[1,4,2,3,2]},{"id":"5be837dd4009","text":"Try a different rhythm rather than waiting for certainty.","weights":[2,3,4,1,2]},{"id":"e828594e69fc","text":"Hold steady until the other person commits too much.","weights":[2,2,2,4,2]},{"id":"22dd59609ef5","text":"Show an intention that conceals the move you actually want.","weights":[2,3,2,1,4]}],"pair":null},{"version":1,"id":"recovery","prompt":"After a difficult exchange, both sides need to recover. What matters most?","category":"combat","options":[{"id":"4b472d479aab","text":"Recover enough to keep applying dependable pressure.","weights":[4,1,2,3,1]},{"id":"95301b15ce43","text":"Use the pause to connect what you learned into a plan.","weights":[2,4,2,2,2]},{"id":"0171d954de51","text":"Stay ready to change direction when the exchange resumes.","weights":[2,2,4,2,2]},{"id":"baa2ff1e47f0","text":"Restore a stable position before taking another risk.","weights":[2,2,1,4,3]},{"id":"e358b5ee141c","text":"Control what the other person thinks you are preparing.","weights":[1,4,2,1,4]}],"pair":null},{"version":1,"id":"teamfight","prompt":"A teammate is drawing pressure while you have room to act. What is your contribution?","category":"combat","options":[{"id":"265a5efaf341","text":"Commit alongside them so the pressure cannot stay one-sided.","weights":[4,1,2,4,1]},{"id":"112e8ca557d4","text":"Coordinate a sequence that makes both contributions count.","weights":[1,4,2,3,2]},{"id":"6f53a4b216ae","text":"Move to whichever position the situation now needs.","weights":[2,2,4,2,2]},{"id":"de023f384d25","text":"Give them a dependable way to recover and regroup.","weights":[3,2,1,4,2]},{"id":"a4447d2324ac","text":"Make the opposition look in the wrong direction at the right time.","weights":[1,3,2,1,4]}],"pair":null},{"version":1,"id":"finalexchange","prompt":"Only one meaningful exchange remains. What would you rather rely on?","category":"combat","options":[{"id":"c08e1465ea96","text":"A clear commitment that uses everything still available.","weights":[4,2,2,3,1]},{"id":"29ebf5aa0928","text":"A response built from the patterns you have verified.","weights":[1,4,2,2,2]},{"id":"4fe5be47da4a","text":"Your ability to adjust faster than the situation changes.","weights":[2,2,4,2,2]},{"id":"886ba2e095d2","text":"A dependable response to the other person committing first.","weights":[2,2,1,4,3]},{"id":"370c01d09551","text":"An expectation you have carefully encouraged them to believe.","weights":[1,4,2,1,4]}],"pair":null},{"version":1,"id":"lost","prompt":"Your group is lost and everyone has a different idea. What do you do first?","category":"everyday","options":[{"id":"d0d01a39faf0","text":"Pick a workable direction and take responsibility for moving.","weights":[4,1,2,3,2]},{"id":"55e51bc38e43","text":"Compare what each person knows before choosing a route.","weights":[1,4,2,2,2]},{"id":"fd441bb90f0c","text":"Try a short route while keeping alternatives open.","weights":[2,2,4,2,2]},{"id":"08ba8b6ead0e","text":"Get everyone to a safe place before making the next decision.","weights":[2,2,1,4,3]},{"id":"313b0086aa00","text":"Find an overlooked shortcut that the group has dismissed.","weights":[1,3,2,1,4]}],"pair":null},{"version":1,"id":"planfails","prompt":"A project plan falls apart just before a deadline. What comes naturally?","category":"everyday","options":[{"id":"ac6f95b239f4","text":"Commit to the essential work and carry it through.","weights":[4,1,3,3,1]},{"id":"b9b6ecc1a3be","text":"Identify the broken dependency and rebuild around it.","weights":[1,4,2,2,2]},{"id":"138bbb92ac2b","text":"Change the approach quickly using what is still available.","weights":[2,3,4,1,2]},{"id":"013b1d666449","text":"Protect the work already completed and limit further damage.","weights":[2,3,1,4,2]},{"id":"9c1de7d3a960","text":"Use the disruption to try an opening the original plan excluded.","weights":[1,3,2,1,4]}],"pair":null},{"version":1,"id":"newgame","prompt":"Friends invite you into a game you do not understand yet. How do you begin?","category":"everyday","options":[{"id":"4c7449ed9509","text":"Try a clear move and learn from the response.","weights":[4,1,3,3,1]},{"id":"222e4f7eb15d","text":"Watch a few turns to understand how choices connect.","weights":[1,4,2,2,2]},{"id":"62033e9272d8","text":"Experiment with small changes as you learn.","weights":[2,2,4,1,2]},{"id":"beff383b5cfa","text":"Start with dependable choices until the risks become clear.","weights":[2,2,1,4,3]},{"id":"48234fcda0bc","text":"Look for assumptions everyone else is taking for granted.","weights":[1,3,2,1,4]}],"pair":null},{"version":1,"id":"disagreement","prompt":"Your group disagrees about what to do next. How do you help?","category":"everyday","options":[{"id":"38e7c9441a32","text":"State a clear position and take responsibility for its consequences.","weights":[4,1,2,4,1]},{"id":"101e941e4ee7","text":"Separate the disagreement into points that can be checked.","weights":[1,4,2,2,2]},{"id":"03c6bbc0254d","text":"Find a flexible compromise and adjust it as you go.","weights":[2,3,4,1,2]},{"id":"1fd84479e7a9","text":"Slow things down so nobody is pressured into a bad decision.","weights":[2,2,1,4,2]},{"id":"1e7f98e0bca5","text":"Reframe the choice so an overlooked option becomes possible.","weights":[2,3,2,1,4]}],"pair":null},{"version":1,"id":"deadline","prompt":"Several unexpected tasks arrive at once. What is your first instinct?","category":"everyday","options":[{"id":"79753bbdbdb1","text":"Choose the most pressing task and commit fully.","weights":[4,1,2,3,1]},{"id":"389108cb4114","text":"Map the dependencies before dividing the time.","weights":[1,4,2,2,3]},{"id":"bc561b761935","text":"Start with something small and switch as priorities change.","weights":[2,2,4,2,2]},{"id":"eed2c3ff948e","text":"Protect the essential commitments from being disrupted.","weights":[2,2,2,4,2]},{"id":"db7d55a1a552","text":"Find a way to change the terms instead of accepting every demand.","weights":[1,4,2,1,4]}],"pair":null},{"version":1,"id":"opportunity","prompt":"You receive an interesting offer with incomplete information. What do you do?","category":"everyday","options":[{"id":"f35caf91ffef","text":"Commit if the core purpose is clear and own the uncertainty.","weights":[4,2,2,3,1]},{"id":"860df9caf0e2","text":"Find the missing information that would change the decision.","weights":[1,4,2,2,2]},{"id":"f7f84d11dd78","text":"Try a limited version that allows a change of direction.","weights":[2,2,4,1,2]},{"id":"b1f6db296341","text":"Keep your dependable commitments intact while considering it.","weights":[2,3,1,4,2]},{"id":"bf36beafd972","text":"Negotiate an unusual arrangement that limits the downside.","weights":[1,4,2,1,4]}],"pair":null},{"version":1,"id":"budget","prompt":"Your team has fewer resources than expected. What do you suggest?","category":"everyday","options":[{"id":"c02ae780a2e9","text":"Put the remaining resources behind one essential objective.","weights":[4,1,2,3,1]},{"id":"68280582fce9","text":"Redesign the sequence so each resource serves more than one step.","weights":[1,4,2,2,2]},{"id":"2c2d9ea669e8","text":"Use whatever is available and adapt the goal as you learn.","weights":[2,3,4,1,2]},{"id":"7b31f17c70d2","text":"Keep a reserve so one mistake cannot end the effort.","weights":[2,2,2,4,2]},{"id":"bec54a70aa8a","text":"Trade an unexpected advantage for something the team actually needs.","weights":[1,3,2,1,4]}],"pair":null},{"version":1,"id":"leadership","prompt":"A team is waiting for someone to take the next step. What role suits you?","category":"everyday","options":[{"id":"3337dd5dc5fa","text":"Make a clear commitment that others can build around.","weights":[4,1,2,4,1]},{"id":"97a7f7801d8b","text":"Connect the scattered information into a useful plan.","weights":[1,4,2,2,3]},{"id":"f2c98b8fa9d1","text":"Go where the team is struggling and adjust as needed.","weights":[2,3,4,1,2]},{"id":"0bae862432c9","text":"Keep everyone grounded and prevent avoidable mistakes.","weights":[2,2,1,4,3]},{"id":"65947999bb89","text":"Notice the opportunity that the usual roles have missed.","weights":[1,3,2,2,4]}],"pair":null},{"version":1,"id":"incomplete","prompt":"You must solve a problem, but the explanation is incomplete. How do you proceed?","category":"everyday","options":[{"id":"b0c1d305db7e","text":"Tackle the part that is clear and build from the result.","weights":[4,1,2,4,1]},{"id":"c8ae3b7dd8be","text":"List what must be true and test the most important assumption.","weights":[1,4,2,2,2]},{"id":"54e26ad65bd1","text":"Try a small experiment and change direction based on feedback.","weights":[2,2,4,1,2]},{"id":"a733da72a81a","text":"Avoid irreversible steps until the situation is better understood.","weights":[2,2,2,4,2]},{"id":"f4b27e076c03","text":"Question the way the problem was framed before accepting it.","weights":[1,4,2,1,4]}],"pair":null},{"version":1,"id":"criticism","prompt":"Someone dismisses an idea you have worked hard on. What do you do next?","category":"everyday","options":[{"id":"fea68e17de35","text":"Demonstrate the useful part through a clear example.","weights":[4,1,2,3,1]},{"id":"8c3560ab1584","text":"Ask which assumption they disagree with and examine it.","weights":[1,4,2,2,3]},{"id":"c77bf5eed081","text":"Rework the approach without becoming attached to its old form.","weights":[2,3,4,1,2]},{"id":"8871d18f5512","text":"Stay composed and decide which feedback is worth acting on.","weights":[2,3,1,4,2]},{"id":"b9da33090e0f","text":"Find a different setting where the overlooked value becomes obvious.","weights":[1,4,2,1,4]}],"pair":null},{"version":1,"id":"groupchange","prompt":"Halfway through a shared activity, the conditions suddenly change. What do you do?","category":"everyday","options":[{"id":"8eebd72d3eb2","text":"Keep the main commitment moving despite the disruption.","weights":[4,1,3,3,1]},{"id":"85131a35b548","text":"Pause long enough to understand the new constraints.","weights":[2,4,2,2,2]},{"id":"63b16b4a925e","text":"Change roles or direction as the new situation demands.","weights":[2,2,4,1,3]},{"id":"91b1d07a894c","text":"Make sure the change does not leave anyone unsupported.","weights":[3,2,1,4,2]},{"id":"7c438d295219","text":"Use the unexpected change to create a new advantage.","weights":[1,4,2,1,4]}],"pair":null},{"version":1,"id":"trust","prompt":"A friend asks you to help with something difficult. What promise feels most natural?","category":"everyday","options":[{"id":"4588f79cc8d9","text":"I will show up and keep working through the hard part.","weights":[4,1,2,4,1]},{"id":"991c4fbbb04b","text":"I will help you understand the problem and plan the steps.","weights":[1,4,2,3,2]},{"id":"9df5a49936a4","text":"I will adjust with you when the first approach does not work.","weights":[2,2,4,1,2]},{"id":"3840275454b5","text":"I will help keep the pressure from overwhelming you.","weights":[2,3,1,4,2]},{"id":"f920466079a3","text":"I will help find an opening that others have overlooked.","weights":[2,3,2,1,4]}],"pair":null},{"version":1,"id":"det-warrior-wizard-1","prompt":"A stubborn problem resists your usual approach. There is time for one substantial change.","category":"determinant","options":[{"id":"bbadaece2617","text":"Make a clear commitment and carry the pressure through.","weights":[4,1,3,3,1]},{"id":"dbe4ed800c13","text":"Connect the evidence into a plan before taking the next step.","weights":[1,4,2,2,2]},{"id":"7f895d7d8805","text":"Try a reversible change and adjust immediately to the response.","weights":[2,2,4,1,2]},{"id":"f02e200be0f5","text":"Keep a stable position and prepare for the next commitment.","weights":[2,2,2,4,2]},{"id":"fab48539a9d5","text":"Encourage a useful expectation, then act through the overlooked opening.","weights":[1,3,2,1,4]}]