create function public.kaidra_awakening_score(questions jsonb,answers jsonb) returns jsonb language plpgsql immutable set search_path='' as $$
declare traits integer[]:=array[0,0,0,0,0];squares integer[]:=array[0,0,0,0,0];q jsonb;o jsonb;i integer;begin
 for q in select value from jsonb_array_elements(questions) loop
  select value into o from jsonb_array_elements(q->'options') where value->>'id'=answers->>(q->>'id');
  if o is not null then for i in 1..5 loop traits[i]:=traits[i]+(o->'weights'->>(i-1))::integer;squares[i]:=squares[i]+((o->'weights'->>(i-1))::integer)^2;end loop;end if;
 end loop;
 return (select jsonb_agg(jsonb_build_object('class_id',id,'score',score,'secondary',secondary,'dominant',dominant) order by score desc,secondary desc,dominant desc,id) from (values
 ('warrior',5*traits[1]+2*traits[4]+traits[3],5*squares[1]+2*squares[4]+squares[3],traits[1]),
 ('wizard',5*traits[2]+2*traits[3]+traits[4],5*squares[2]+2*squares[3]+squares[4],traits[2]),
 ('ninja',5*traits[3]+2*traits[5]+traits[2],5*squares[3]+2*squares[5]+squares[2],traits[3]),
 ('guardian',5*traits[4]+2*traits[2]+traits[1],5*squares[4]+2*squares[2]+squares[1],traits[4]),
 ('rogue',5*traits[5]+2*traits[2]+traits[3],5*squares[5]+2*squares[2]+squares[3],traits[5])
 ) scores(id,score,secondary,dominant));
end $$;

create function public.kaidra_awakening_view(target_session uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare s public.awakening_sessions;q jsonb;identity jsonb;answered integer;begin
 select * into s from public.awakening_sessions where id=target_session and user_id=auth.uid();
 if s.id is null then raise exception 'Determination session unavailable';end if;
 identity:=public.kaidra_battle_identity(auth.uid());
 select count(*) into answered from jsonb_object_keys(s.answers);
 select value into q from jsonb_array_elements(s.questions) where not(s.answers ? (value->>'id')) limit 1;
 return jsonb_build_object('session_id',s.id,'version',s.version,'answered',answered,'total',jsonb_array_length(s.questions),'identity',identity,
 'question',case when identity is null and q is not null then jsonb_build_object('id',q->>'id','prompt',q->>'prompt','options',(select jsonb_agg(jsonb_build_object('id',o->>'id','text',o->>'text')) from jsonb_array_elements(q->'options') o)) end);
end $$;

create function public.kaidra_awakening_begin() returns jsonb language plpgsql security definer set search_path='' as $$
declare s public.awakening_sessions;identity jsonb;questions jsonb;begin
 if auth.uid() is null or not exists(select 1 from public.profiles where id=auth.uid() and not coalesce(is_banned,false)) then raise exception 'An active Kaidra account is required';end if;
 perform pg_advisory_xact_lock(hashtextextended('kaidra:awakening:'||auth.uid()::text,0));
 identity:=public.kaidra_battle_identity(auth.uid());if identity is not null then return jsonb_build_object('identity',identity,'question',null);end if;
 select * into s from public.awakening_sessions where user_id=auth.uid();
 if s.id is null then
  select jsonb_agg(jsonb_build_object('id',id,'prompt',prompt,'category',category,'options',options) order by random()) into questions
  from ((select * from public.awakening_questions where version=1 and active and category='combat' order by random() limit 6)
  union all(select * from public.awakening_questions where version=1 and active and category='everyday' order by random() limit 6)) pool;
  -- Answer order is randomized once and then frozen with the session snapshot.
  select jsonb_agg(q||jsonb_build_object('options',(select jsonb_agg(o order by random()) from jsonb_array_elements(q->'options') o))) into questions from jsonb_array_elements(questions) q;
  if jsonb_array_length(questions)<>12 then raise exception 'Determination pool is not ready';end if;
  insert into public.awakening_sessions(user_id,questions) values(auth.uid(),questions) returning * into s;
 else update public.awakening_sessions set expires_at=now()+interval '7 days' where id=s.id returning * into s;end if;
 return public.kaidra_awakening_view(s.id);
end $$;

create function public.kaidra_awakening_progress() returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('identity',public.kaidra_battle_identity(auth.uid()),'answered',coalesce((select count(*) from public.awakening_sessions s cross join lateral jsonb_object_keys(s.answers) a where s.user_id=auth.uid()),0));
$$;

create function public.kaidra_awakening_finalize(target_session uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare s public.awakening_sessions;scores jsonb;extras jsonb;selected_pair text[];identity jsonb;begin
 if auth.uid() is null then raise exception 'Sign in to determine your class';end if;
 perform pg_advisory_xact_lock(hashtextextended('kaidra:awakening:'||auth.uid()::text,0));
 select * into s from public.awakening_sessions where id=target_session and user_id=auth.uid() for update;
 if s.id is null then raise exception 'Determination session unavailable';end if;
 identity:=public.kaidra_battle_identity(auth.uid());if identity is not null then return public.kaidra_awakening_view(s.id);end if;
 if s.expires_at<=now() then raise exception 'Resume your determination before answering';end if;
 if exists(select 1 from jsonb_array_elements(s.questions) q where not(s.answers ? (q->>'id'))) then raise exception 'Complete each determination question';end if;
 scores:=public.kaidra_awakening_score(s.questions,s.answers);
 if not s.determinants_added and (scores->0->>'score')::integer-(scores->1->>'score')::integer<=8 then
  select array_agg(id order by id) into selected_pair from unnest(array[scores->0->>'class_id',scores->1->>'class_id']) id;
  select jsonb_agg(jsonb_build_object('id',id,'category',category,'prompt',prompt,'options',options) order by id) into extras from
  (select * from public.awakening_questions where version=s.version and active and category='determinant' and awakening_questions.pair=selected_pair order by id limit 2) pool;
  if coalesce(jsonb_array_length(extras),0)<>2 then raise exception 'Determination scenarios are unavailable';end if;
  select jsonb_agg(q||jsonb_build_object('options',(select jsonb_agg(o order by random()) from jsonb_array_elements(q->'options') o))) into extras from jsonb_array_elements(extras) q;
  update public.awakening_sessions set questions=questions||extras,determinants_added=true where id=s.id;
  return public.kaidra_awakening_view(s.id);
 end if;
 insert into public.battle_identities(user_id,class_id,determination_version) values(auth.uid(),scores->0->>'class_id',s.version) on conflict(user_id) do nothing;
 update public.awakening_sessions set completed_at=now(),result_class=(select class_id from public.battle_identities where user_id=auth.uid()),score_audit=scores where id=s.id;
 perform public.kaidra_social_signal(auth.uid());
 return public.kaidra_awakening_view(s.id);
end $$;

create function public.kaidra_awakening_answer(target_session uuid,question_id text,answer_id text) returns jsonb language plpgsql security definer set search_path='' as $$
declare s public.awakening_sessions;current_question jsonb;begin
 if auth.uid() is null then raise exception 'Sign in to determine your class';end if;
 perform pg_advisory_xact_lock(hashtextextended('kaidra:awakening:'||auth.uid()::text,0));
 select * into s from public.awakening_sessions where id=target_session and user_id=auth.uid() for update;
 if s.id is null then raise exception 'Determination session unavailable';end if;
 if exists(select 1 from public.battle_identities where user_id=auth.uid()) then return public.kaidra_awakening_view(s.id);end if;
 if s.expires_at<=now() then raise exception 'Resume your determination before answering';end if;
 if s.answers ? question_id then
  if s.answers->>question_id=answer_id then return public.kaidra_awakening_view(s.id);end if;
  raise exception 'This decision has already been confirmed';
 end if;
 select value into current_question from jsonb_array_elements(s.questions) where not(s.answers ? (value->>'id')) limit 1;
 if current_question->>'id' is distinct from question_id or answer_id is null or not exists(select 1 from jsonb_array_elements(current_question->'options') o where o->>'id'=answer_id) then raise exception 'Choose a valid answer to the current question';end if;
 update public.awakening_sessions set answers=answers||jsonb_build_object(question_id,answer_id) where id=s.id returning * into s;
 if not exists(select 1 from jsonb_array_elements(s.questions) q where not(s.answers ? (q->>'id'))) then return public.kaidra_awakening_finalize(s.id);end if;
 return public.kaidra_awakening_view(s.id);
end $$;
create function public.kaidra_awakening_acknowledge() returns void language plpgsql security definer set search_path='' as $$begin
 update public.battle_identities set acknowledged_at=coalesce(acknowledged_at,now()) where user_id=auth.uid();
 if not found then raise exception 'Complete your determination first';end if;
end $$;

do $$declare signature text;begin
 foreach signature in array array['kaidra_immutable_class()','kaidra_guard_profile_identity()','kaidra_awakening_score(jsonb,jsonb)','kaidra_awakening_view(uuid)'] loop
 execute 'revoke all on function public.'||signature||' from public,anon,authenticated';end loop;
 foreach signature in array array['kaidra_battle_identity(uuid)','kaidra_profile_social(uuid)','kaidra_battle_state(uuid)','kaidra_battle_create(uuid,uuid,text,text,jsonb,uuid)','kaidra_battle_action(uuid,text,text)','kaidra_awakening_progress()','kaidra_awakening_begin()','kaidra_awakening_answer(uuid,text,text)','kaidra_awakening_finalize(uuid)','kaidra_awakening_acknowledge()'] loop
 execute 'revoke all on function public.'||signature||' from public,anon';execute 'grant execute on function public.'||signature||' to authenticated';end loop;
end $$;
notify pgrst,'reload schema';
commit;
